pub fn bash_build_is_name(text: String) -> bool {
    match (*crate::v2_std_text::string_head(crate::std_coercion::unicode_scalar_unfold(text.clone()))).clone() {
    CharResult::CharFound { value: first, .. } => (crate::v2_std_text::string_all_chars_in(crate::std_coercion::unicode_scalar_unfold(text.clone()), crate::std_coercion::unicode_scalar_unfold(bash_build_name_alphabet())) && crate::v2_std_text::string_contains_char(crate::std_coercion::unicode_scalar_unfold(bash_build_name_lead_alphabet()), first.clone())),
    CharResult::CharAbsent => false,
}
}

pub fn bash_build_is_bare_word(text: String) -> bool {
    (!crate::v2_std_text::string_is_empty(crate::std_coercion::unicode_scalar_unfold(text.clone())) && crate::v2_std_text::string_all_chars_in(crate::std_coercion::unicode_scalar_unfold(text.clone()), crate::std_coercion::unicode_scalar_unfold(bash_build_bare_word_alphabet())))
}

pub fn bash_build_is_case_pattern(text: String) -> bool {
    (!crate::v2_std_text::string_is_empty(crate::std_coercion::unicode_scalar_unfold(text.clone())) && crate::v2_std_text::string_all_chars_in(crate::std_coercion::unicode_scalar_unfold(text.clone()), crate::std_coercion::unicode_scalar_unfold(bash_build_case_pattern_alphabet())))
}

pub fn bash_build_is_digits(text: String) -> bool {
    (!crate::v2_std_text::string_is_empty(crate::std_coercion::unicode_scalar_unfold(text.clone())) && crate::v2_std_text::string_all_chars_in(crate::std_coercion::unicode_scalar_unfold(text.clone()), crate::std_coercion::unicode_scalar_unfold(bash_build_digit_alphabet())))
}

pub fn bash_build_comment(text: String) -> Option<Rc<Node>> {
    match (*crate::v2_std_text::string_head(crate::std_coercion::unicode_scalar_unfold(text.clone()))).clone() {
    CharResult::CharFound { value: head, .. } => if (head.clone() == bash_build_char_hash()) {
        if crate::v2_std_text::string_contains_char(crate::std_coercion::unicode_scalar_unfold(text.clone()), bash_build_char_newline()) {
            std::option::Option::None
        } else {
            Some(bash_build_stmt_with_body("bash_production_fold_comment".to_string(), Rc::new(vec![bash_build_name_atom(text.clone())])))
        }
    } else {
        std::option::Option::None
    },
    CharResult::CharAbsent => std::option::Option::None,
}
}

