pub fn bash_build_test_operators() -> Rc<Vec<String>> {
    thread_local! {
        static CACHED: Rc<Vec<String>> = {
            Rc::new(vec!["-b".to_string(), "-c".to_string(), "-d".to_string(), "-e".to_string(), "-f".to_string(), "-g".to_string(), "-G".to_string(), "-h".to_string(), "-k".to_string(), "-p".to_string(), "-r".to_string(), "-S".to_string(), "-s".to_string(), "-t".to_string(), "-u".to_string(), "-v".to_string(), "-w".to_string(), "-x".to_string(), "-O".to_string(), "-N".to_string(), "-R".to_string(), "-z".to_string(), "-n".to_string(), "-o".to_string(), "-ef".to_string(), "-nt".to_string(), "-ot".to_string(), "=".to_string(), "==".to_string(), "!=".to_string(), "-eq".to_string(), "-ne".to_string(), "-lt".to_string(), "-le".to_string(), "-gt".to_string(), "-ge".to_string(), "=~".to_string(), "-a".to_string()])
        };
    }
    CACHED.with(|c: &Rc<Vec<String>>| c.clone())
}

pub fn bash_build_test_operator_scanned(mut __tco_loop_xs: Rc<Vec<String>>, mut __tco_loop_op: String, mut __tco_loop_index: i64) -> bool {
    { loop {
        #[allow(unused_mut)]
        let mut xs = __tco_loop_xs;
        #[allow(unused_mut)]
        let mut op = __tco_loop_op;
        #[allow(unused_mut)]
        let mut index = __tco_loop_index;
        match v1_rt::list_get_optional(&xs, index.clone()) {
    Some(head) => { if (head.clone() == op.clone()) {
            break true;
} else {
            {
                let __tco_0 = xs;
let __tco_1 = op;
let __tco_2 = v1_rt::int_add(index, 1);
__tco_loop_xs = __tco_0;
__tco_loop_op = __tco_1;
__tco_loop_index = __tco_2;
continue;
}
} },
    std::option::Option::None => { break false; },
}
} }
}

pub fn bash_build_is_test_operator(op: String) -> bool {
    bash_build_test_operator_scanned(bash_build_test_operators(), op, 0)
}

pub fn bash_build_word_test_operator(op: String) -> Option<Rc<Node>> {
    if bash_build_is_test_operator(op.clone()) {
        Some(bash_build_word_kinded("bash_fold_word_kind_test_operator".to_string(), op.clone()))
    } else {
        std::option::Option::None
    }
}

pub fn bash_build_test_comparison(left: Rc<Node>, op: String, right: Rc<Node>, spelling: TestBracketSpelling) -> Rc<Node> {
    {
        let op_word = match bash_build_word_test_operator(op.clone()) {
    Some(w) => w.clone(),
    std::option::Option::None => bash_build_word_kinded("bash_build_refused_test_operator".to_string(), op.clone()),
};
bash_build_test_bracket(Rc::new(vec![left.clone(), op_word.clone(), right.clone()]), spelling)
}
}

pub fn bash_build_single_quoted_forbidden() -> String {
    thread_local! {
        static CACHED: String = {
            "'`\\\n!".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn bash_build_is_single_quoted_word(text: String) -> bool {
    (!crate::v2_std_text::string_is_empty(crate::std_coercion::unicode_scalar_unfold(text.clone())) && !crate::v2_std_text::string_any_char_in(crate::std_coercion::unicode_scalar_unfold(text.clone()), crate::std_coercion::unicode_scalar_unfold(bash_build_single_quoted_forbidden())))
}

pub fn bash_build_single_quoted_word(text: String) -> Option<Rc<Node>> {
    if bash_build_is_single_quoted_word(text.clone()) {
        Some(bash_build_word_kinded("bash_fold_word_kind_single_quoted".to_string(), text.clone()))
    } else {
        std::option::Option::None {}
    }
}

pub fn bash_build_json_word_forbidden() -> String {
    thread_local! {
        static CACHED: String = {
            bash_build_single_quoted_forbidden()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn bash_build_char_open_brace() -> Char { 123 }

pub fn bash_build_is_json_word(text: String) -> bool {
    ((bash_build_is_single_quoted_word(text.clone()) && crate::v2_std_text::string_contains_char(crate::std_coercion::unicode_scalar_unfold(text.clone()), bash_build_char_open_brace())) && crate::v2_std_text::string_contains_char(crate::std_coercion::unicode_scalar_unfold(text.clone()), bash_build_char_close_brace()))
}

pub fn bash_build_json_word(text: String) -> Option<Rc<Node>> {
    if bash_build_is_json_word(text.clone()) {
        Some(bash_build_word_kinded("bash_fold_word_kind_single_quoted".to_string(), text.clone()))
    } else {
        std::option::Option::None {}
    }
}

